 body={"seed":42,"base_row_count":40,"generated_files":["crm_customers.parquet","sales_orders.parquet","order_items.parquet","order_payments.parquet","billing_subscriptions.parquet","marketing_leads.parquet","payment_events_wave1.parquet","payment_events_wave3.parquet"],"true_total_order_revenue_usd":35710.5,"naive_fanout_inflated_revenue_usd":93766.0,"expected_fanout_multiplier":2.63,"wave1_payment_mean_usd":119.5,"wave3_payment_mean_cents":11950.0,"expected_trap_05_anomaly_count":1,"planted_traps":[{"trap_id":"TRAP-01","category":"homonym_chasm","left_dataset":"billing_subscriptions","left_field":"account_id","right_dataset":"marketing_leads","right_field":"account_id","expected_action":"require_steward_verification_then_forbidden_join","description":"Both tables use sequential integer surrogate account_id (1..N) for unrelated entity domains (Billing Tax Accounts vs Ad Marketing Leads)."},{"trap_id":"TRAP-02","category":"cryptic_synonym_fk","left_dataset":"sales_orders","left_field":"cust_ref_key","right_dataset":"crm_customers","right_field":"party_uuid","expected_action":"sync_joinable_with","description":"Zero column-name similarity, but >98% value inclusion ratio and clean N:1 cardinality."},{"trap_id":"TRAP-03","category":"nm_fanout_inflation","left_dataset":"order_items","left_field":"order_id","right_dataset":"order_payments","right_field":"order_id","expected_action":"pre_aggregate_before_join","description":"Joining multi-row order_items to multi-row order_payments on order_id inflates payment revenue by ~2.5x."},{"trap_id":"TRAP-04","category":"temporal_schema_and_unit_drift","left_dataset":"payment_events_wave1","left_field":"amount","right_dataset":"payment_events_wave3","right_field":"amount","expected_action":"mark_drifted_and_require_unit_conversion","description":"Wave 3 renames user_id -> client_id and shifts amount from USD (~120.0) to integer cents (~12000.0, 100x scale shift)."},{"trap_id":"TRAP-05","category":"non_sql_algorithmic_anomaly","left_dataset":"sales_orders","left_field":"order_total_usd","right_dataset":"sales_orders","right_field":"status","expected_action":"execute_sandboxed_python_algorithm_and_promote_aad_skill","description":"Detect outlier orders (z_score > 3.0) and composite churn risk via sandboxed Python algorithm."}],"stat_traps":[]}

