 body={"id":1,"jsonrpc":"2.0","result":{"tools":[{"description":"List all hydrated, SHA-256-pinned built-in statistical algorithms.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object"},"name":"algorithm_browse"},{"description":"Health-check MCP tool returning a greeting from data-engine.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"name":{"description":"Optional name of the caller or entity to greet (defaults to 'world').","type":["string","null"]}},"type":"object"},"name":"hello"},{"description":"Compute Pearson/Spearman/Kendall correlation matrices with FDR adjustment, partial correlations, and VIF multicollinearity diagnostics.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"columns":{"description":"Numeric column names to include in correlation and VIF analysis.","items":{"type":"string"},"type":"array"},"control_cols":{"description":"Optional control columns for partial correlation computation.","items":{"type":"string"},"type":["array","null"]},"correction":{"description":"Multiple-testing correction method (default 'fdr_bh').","type":["string","null"]},"input_binding":{"description":"Dataset input binding object containing dataset_name and parquet_path."},"methods":{"description":"Correlation methods to compute (e.g. ['pearson', 'spearman', 'kendall']).","items":{"type":"string"},"type":["array","null"]},"sampling":{"description":"Optional seeded sampling specification object."}},"required":["input_binding","columns"],"type":"object"},"name":"stat_correlation_vif"},{"description":"Compute distributional moments, quantiles, Shapiro-Wilk/D'Agostino normality, outlier counts, and learned field traits.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"columns":{"description":"List of numeric column names to describe and diagnose.","items":{"type":"string"},"type":"array"},"input_binding":{"description":"Dataset input binding object containing dataset_name and parquet_path."},"sampling":{"description":"Optional seeded sampling specification object."}},"required":["input_binding","columns"],"type":"object"},"name":"stat_describe_and_check"},{"description":"Execute parametric/non-parametric hypothesis tests with assumption checks, CIs, BH-FDR correction, and Simpson's paradox stratification.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"alpha":{"description":"Significance level alpha (default 0.05).","format":"double","type":["number","null"]},"alternative":{"description":"Alternative hypothesis ('two-sided', 'less', or 'greater').","type":["string","null"]},"col_a":{"description":"First column name for paired tests.","type":["string","null"]},"col_b":{"description":"Second column name for paired tests.","type":["string","null"]},"correction":{"description":"Multiple-comparison correction method (e.g. none, bonferroni, fdr_bh).","type":["string","null"]},"group_col":{"description":"Grouping column name for two-sample or multi-group comparisons.","type":["string","null"]},"input_binding":{"description":"Dataset input binding object containing dataset_name and parquet_path."},"method":{"description":"Hypothesis test method (e.g. welch_t, mann_whitney_u, anova, kruskal_wallis, chi2_independence).","type":"string"},"sampling":{"description":"Optional seeded sampling specification object."},"segment_col":{"description":"Segment column name for multi-segment testing with multiple-comparison correction.","type":["string","null"]},"stratify_by":{"description":"Stratification column name for Simpson's paradox detection.","type":["string","null"]},"value_col":{"description":"Primary measurement or outcome column name.","type":"string"}},"required":["input_binding","method","value_col"],"type":"object"},"name":"stat_hypothesis_test"},{"description":"Compute prospective/retrospective statistical power, required sample size, or MDE.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"alpha":{"description":"Significance level alpha (default 0.05).","format":"double","type":["number","null"]},"alternative":{"description":"Alternative hypothesis ('two-sided', 'larger', or 'smaller').","type":["string","null"]},"effect_size":{"description":"Standardized effect size (e.g. Cohen's d or f).","format":"double","type":["number","null"]},"n_per_group":{"description":"Sample size per group.","format":"uint","minimum":0,"type":["integer","null"]},"num_groups":{"description":"Number of groups for ANOVA power calculations (default 2).","format":"uint","minimum":0,"type":["integer","null"]},"p1":{"description":"Baseline proportion p1 for proportion tests.","format":"double","type":["number","null"]},"p2":{"description":"Variant proportion p2 for proportion tests.","format":"double","type":["number","null"]},"power":{"description":"Target statistical power (1 - beta), e.g. 0.80.","format":"double","type":["number","null"]},"ratio":{"description":"Group allocation ratio n2/n1 (default 1.0).","format":"double","type":["number","null"]},"solve_for":{"description":"Quantity to solve for ('sample_size', 'power', or 'effect_size').","type":"string"},"test_type":{"description":"Statistical test type (e.g. two_sample_t, two_proportion_z, one_way_anova).","type":"string"}},"required":["test_type","solve_for"],"type":"object"},"name":"stat_power_analysis"},{"description":"Fit OLS, GLM, or Huber robust regression with HC3 SEs, Breusch-Pagan, Durbin-Watson, and Cook's distance diagnostics.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"add_intercept":{"description":"Whether to include an intercept term (default true).","type":["boolean","null"]},"feature_cols":{"description":"List of predictor/feature column names.","items":{"type":"string"},"type":"array"},"input_binding":{"description":"Dataset input binding object containing dataset_name and parquet_path."},"model_type":{"description":"Regression model family (e.g. ols, huber, glm_binomial, glm_poisson).","type":"string"},"sampling":{"description":"Optional seeded sampling specification object."},"target_col":{"description":"Dependent target column name.","type":"string"}},"required":["input_binding","model_type","target_col","feature_cols"],"type":"object"},"name":"stat_regression_fit"},{"description":"Perform STL decomposition, ADF/KPSS stationarity, ACF/PACF, spurious cross-series correlation checks, and ETS/ARIMA forecasting.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"anomaly_z_threshold":{"description":"Optional z-score threshold for residual anomaly detection.","format":"double","type":["number","null"]},"compare_col":{"description":"Optional second series column for spurious cross-series correlation diagnostics.","type":["string","null"]},"forecast_horizon":{"description":"Optional number of future steps to forecast.","format":"uint","minimum":0,"type":["integer","null"]},"input_binding":{"description":"Dataset input binding object containing dataset_name and parquet_path."},"model":{"description":"Forecasting model family (e.g. ets, arima).","type":["string","null"]},"period":{"description":"Optional seasonal period length.","format":"uint","minimum":0,"type":["integer","null"]},"sampling":{"description":"Optional seeded sampling specification object."},"time_col":{"description":"Timestamp or sequential time index column name.","type":"string"},"value_col":{"description":"Primary time-series value column name.","type":"string"}},"required":["input_binding","time_col","value_col"],"type":"object"},"name":"stat_timeseries_analyze"},{"description":"Return zoomed-in nested Arrow schema anatomy for a dataset or side-by-side schema cards, type compatibility, Venn/Sankey overlap, and fan-out diagnostics for a join hypothesis.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"target_id":{"description":"Canonical dataset ID or join hypothesis ID to inspect.","type":"string"},"target_kind":{"description":"Target anatomy kind: 'dataset' or 'join'.","type":"string"}},"required":["target_kind","target_id"],"type":"object"},"name":"topology_field_anatomy"},{"description":"Return a bounded multi-layer SemanticTopologyGraph (Business Concepts/Metrics -> Datasets -> Fields, JOINABLE_WITH, FORBIDDEN_JOIN, fan-out & CONFOUNDED_BY overlays) for ./SemanticTopologyWrapper.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"dataset_ids":{"description":"Optional list of dataset IDs to restrict the subgraph.","items":{"type":"string"},"type":["array","null"]},"epistemic_status":{"description":"Optional epistemic status filters (e.g. ['verified', 'empirically_tested']).","items":{"type":"string"},"type":["array","null"]},"focus_node_id":{"description":"Optional focus node ID for bounded ego-graph traversal.","type":["string","null"]},"hops":{"description":"Maximum ego-graph hop depth from focus_node_id.","format":"uint8","maximum":255,"minimum":0,"type":["integer","null"]},"include_fields":{"description":"Whether to include Layer 0 field nodes.","type":["boolean","null"]},"include_forbidden":{"description":"Whether to include FORBIDDEN_JOIN edges.","type":["boolean","null"]},"include_semantics":{"description":"Whether to include Layer 2 semantic concept/metric overlays.","type":["boolean","null"]},"lens":{"description":"Topology projection lens ('semantic_3layer', 'er_join', or 'lineage_overlay').","type":["string","null"]},"provenance_run_id":{"description":"Optional ProvenanceRun ID for lineage overlay highlighting.","type":["string","null"]},"source_id":{"description":"Optional source identifier filter.","type":["string","null"]}},"type":"object"},"name":"topology_graph"},{"description":"Deterministically recommend ranked Vega-Lite v5 or Apache ECharts DataVisualSpec candidates from dataset schema and profile statistics.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"dataset_name":{"description":"Registered dataset name in the topology catalog.","type":["string","null"]},"max_recommendations":{"description":"Maximum number of ranked recommendations to return.","format":"uint","minimum":0,"type":["integer","null"]},"parquet_path":{"description":"Optional direct Parquet file path to profile and recommend visuals for.","type":["string","null"]},"renderer":{"description":"Preferred chart renderer ('vega_lite' or 'echarts').","type":["string","null"]}},"type":"object"},"name":"visual_recommend"},{"description":"Validate semantic/fan-out guardrails, execute bounded aggregation or seeded sampling with ProvenanceRun tracking, and return a canvas-ready DataVisualSpec for ./DataVisualExplorerWrapper.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"chart_family":{"description":"Chart family identifier (e.g. bar, line, scatter, histogram).","type":["string","null"]},"data_binding":{"description":"Data binding object specifying dataset, parquet path, SQL, or query plan."},"description":{"description":"Optional chart description.","type":["string","null"]},"question":{"description":"Optional analytical question associated with the visual.","type":["string","null"]},"renderer":{"description":"Chart renderer ('vega_lite' or 'echarts').","type":["string","null"]},"sampling":{"description":"Optional seeded visual sampling specification object."},"spec":{"description":"Renderer-specific visualization specification object."},"title":{"description":"Optional human-readable chart title.","type":["string","null"]}},"required":["data_binding","spec"],"type":"object"},"name":"visual_render_spec"}]}}
